A=(0,0);
B=(12,0);
C=(6,-6);
D=(6,-22);
E=(0,-16);
F=(12,-16);
M=(2D+E)/3;
N=(5D+F)/6;
P=(2C+B)/3;
Q=(2A+C)/3;

